def reset(self):
    super().reset()
    self._buffer.clear()

def sample(self, t, dt):
    """Store current incident waves into the delay buffer."""
    self._buffer.add(t, np.array([self.inputs[0], self.inputs[1]]))

def _eval(self, rf_in):
    x = rf_in
    if self._x_sat is not None and abs(x) > self._x_sat:
        return np.copysign(self._y_sat, x)
    return self._a1 * x + self._a3 * x ** 3

